head.script:
scwin.onpageload = function () {
    // Tab 으로 포커스된 항목 출력
    document.getElementById(dp_date.id).addEventListener("focusin", function (e) {
        scwin.setReturnValue("포커스 항목 : " + e.target.getAttribute("aria-valuetext") + " / 선택값 : " + dp_date.getItemValue("year") + "년");
    });
};

scwin.btn_setValue_onclick = function (e) {
    dp_date.setValue("20200101");
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
